 public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play");var forest=GameObject.Find("Forest - imported dirt road environment");string folder="Assets/Game/Generated/AuthoredForestPajero";int windCount=0;
 foreach(var f in forest.GetComponentsInChildren<MeshFilter>()){var wind=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Game/Generated/LivingForest/Living_"+f.name+".asset");if(wind==null||wind.vertexCount!=f.sharedMesh.vertexCount||!wind.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.TexCoord2))continue;var anchors=new List<Vector4>();wind.GetUVs(2,anchors);if(anchors.Count!=f.sharedMesh.vertexCount)continue;var mesh=UnityEngine.Object.Instantiate(f.sharedMesh);mesh.SetUVs(2,anchors);string path=folder+"/Original wind "+f.name+".asset";AssetDatabase.CreateAsset(mesh,path);f.sharedMesh=mesh;var m=f.GetComponent<Renderer>().sharedMaterial;bool trunk=m.name.Contains("Trunk");m.SetFloat("_TreeSway",trunk?.008f:.014f);m.SetFloat("_LeafFlutter",trunk?0:.035f);EditorUtility.SetDirty(m);PrefabUtility.RecordPrefabInstancePropertyModifications(f);windCount++;}
 if(GameObject.Find("Road details - supplied forest mud puddle")!=null)throw new Exception("Mud already placed");var root=new GameObject("Road details - supplied forest mud puddle");var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Art/RoadMud/forest-puddle.fbx");var materials=new Dictionary<string,Material>();
